import {areas,vocabulary,kanaFamilies,grammar,scenarios,companions,curriculum,contentManifest,validateContent} from './data.js';
import {getState,update,exportSave,importSave,resetSave} from './state.js';
import {companionState,COMPANION_REACTIONS,COMPANION_EVENTS,emitCompanion,initializeCompanion,subscribeCompanion} from './companion.js';
import {playJapanese,audioCapability,getJapaneseVoices,audioDiagnostics} from './audio.js';
import {culturalItems,culturalArtwork,validateCulturalItems} from './cultural-items.js';
import {STOREKEEPER,SHOP_BRANDING,STOREKEEPER_REACTION_MAP,storekeeperVisitLine} from './storekeeper.js';
import {mountRegisteredScenes} from './scenes.js';
import {acquireItem,isDiscovered,isOwned,acknowledgeCulturalItem,placeOwnedItem,removePlacedItem,roomPlacements,roomZoneForItem,syncCulturalDiscoveries,recordShopVisit,ROOM_ZONES} from './engine.js';
import {shuffle,mastery,skillScores,nextSkill,dueWords,weakWords,recordWord,recordKana,recordAnswerResult,evaluateAnswer,evaluateConversationAnswer,createQuestion,buildSession,buildFocusSession,recordFocusSession,focusResumeIndex,FOCUS_PROFILES,completeGrammar,completeConversation,completeSession,achievementData,journeyItems,mistakeItems,dailyQuests,weeklyQuest,currentGrammar,activeCompanion,nodeUnlocked,nodeComplete,completeNode,curriculumProgress,stageLabel,gardenProgress,syncGardenProgress,GARDEN_UNLOCKS,JOURNEY_CHAPTERS,journeyMap,recommendNext,curriculumItems,journeyNodeProgress} from './engine.js';

const app=document.querySelector('#app');
let view='home',session=null,journalType='words',conversationTyping=true,journeySelection=null;
function persistSession(){update(s=>s.activeSession=session?{id:session.id,kind:session.kind,title:session.title,nodeId:session.nodeId||null,index:session.index??null,score:session.score??0,answered:Boolean(session.answered),focus:Boolean(session.focus),duration:session.duration||null,gardenStartScore:session.gardenStartScore??null,conversation:Boolean(session.conversation),scenarioId:session.sc?.id||null,sceneIndex:session.sceneIndex??null}:null)}
const nav=[['home','⌂','Home'],['learn','本','Learn'],['journey','🗺','Journey'],['garden','🌸','Garden'],['room','⌑','Room'],['shop','🏪','Shop'],['journal','言','Journal'],['stats','▥','Progress'],['companion','♡','Sakura']];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function level(){return Math.floor(getState().xp/100)+1}
function shell(content,focus=false){if(focus)return `<div class="focus-shell"><main class="focus-main">${content}</main></div>`;const s=getState(),presence=companionState(),reaction=COMPANION_REACTIONS[presence.reaction]||COMPANION_REACTIONS.idle;return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">日</span><span>Nihongo <em>Quest</em></span></div><nav class="nav">${nav.map(n=>navButton(n)).join('')}</nav><div class="sidebar-bottom"><button class="companion-mini ${reaction.tone}" data-go="companion"><img src="./assets/sakura-companion.webp" alt=""><div><strong>Sakura <span>${reaction.emoji}</span></strong><small>${esc(presence.message||reaction.message)}</small></div></button></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">Level ${level()} · ${s.studyDays.length} study days</div></div><div class="topstats"><span class="stat-pill">🔥 ${s.streak}</span><span class="stat-pill">✦ ${s.xp}</span><span class="stat-pill petal-pill">✓ ${masteredCount()} mastered</span></div></header>${sakuraPresence('shell')}${content}</main><nav class="mobile-nav">${nav.map(n=>navButton(n)).join('')}</nav></div>`}
function sakuraPresence(surface){const presence=companionState(),reaction=COMPANION_REACTIONS[presence.reaction]||COMPANION_REACTIONS.idle;return `<aside class="sakura-presence sakura-presence-${surface}" aria-label="Sakura's current reaction"><img src="./assets/sakura-companion.webp" alt="Sakura, your learning companion" loading="lazy" decoding="async"><div><div class="eyebrow">Sakura · ${reaction.label}</div><p>${esc(presence.message||reaction.message)}</p></div></aside>`}
function navButton([id,icon,label]){return `<button class="nav-btn ${view===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span>${label}</button>`}
function render(){if(session){app.innerHTML=shell(renderSession(),session.focus);bindShell();bindSession();return}const renders={home:homeView,learn:learnView,journey:journeyView,garden:gardenView,room:roomView,shop:shopView,journal:journalView,stats:statsView,companion:companionView,studio:studioView,settings:settingsView};let content=(renders[view]||homeView)();if(view==='settings')content+=settingsAudioCard();app.innerHTML=shell(content);bindShell();bindView();bindJourney();bindAudioSettings();bindRoom()}
function navigate(destination){if(session)persistSession();session=null;if(destination==='shop'&&view!=='shop')recordShopVisit();view=destination;render()}
function bindShell(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go))}
function masteredCount(){return Object.values(getState().reviews).filter(r=>mastery(r)>=4).length}
function shopView(){const s=getState(),c=s.culture||{discovered:[],owned:[],shopVisits:0},featured=culturalItems.find(x=>c.discovered.includes(x.id)&&!c.owned.includes(x.id))||culturalItems.find(x=>c.discovered.includes(x.id));return `<div><div class="eyebrow">Cultural Collection</div><h1 class="page-title">Aoi-san’s Shop</h1><p class="subtitle">${storekeeperVisitLine(c.shopVisits||1)}</p></div><section class="card shopkeeper-card"><div class="shopkeeper-placeholder" aria-label="Placeholder portrait for Aoi-san">👵</div><div><div class="eyebrow">${STOREKEEPER.displayName} · ${STOREKEEPER.role}</div><h2>Everything here has a story.</h2><p>Discover objects through meaningful learning, read their context, hear their names, and collect favourites for Sakura’s room.</p><button class="btn btn-ghost btn-small" data-go="room">Visit Sakura’s room</button></div></section><section class="card shop-featured"><div><div class="eyebrow">${featured?'Featured suggestion':'Next discovery'}</div><h2>${featured?featured.japanese:'A mystery is still unfolding'}</h2><p>${featured?featured.summary:'Complete Journey chapters and learning milestones to reveal cultural objects.'}</p>${featured?`<button class="btn btn-primary" data-culture-view="${featured.id}">View knowledge card</button>`:'<button class="btn btn-ghost" data-go="journey">Continue the Journey</button>'}</div><span class="culture-placeholder" aria-hidden="true">${featured?'◇':'?'}</span></section><div class="section-head section"><h2>Collection library</h2><span>${c.discovered.length} / ${culturalItems.length} discovered · ${c.owned.length} owned</span></div><div class="culture-grid">${culturalItems.map(item=>cultureCard(item,c)).join('')}</div></div>`}
function cultureArt(item,variant='card',alt=item.english){const source=culturalArtwork(item,variant);return source?`<img src="${source}" alt="${alt}" loading="lazy" decoding="async" onerror="this.hidden=true;this.parentElement.classList.add('culture-art-fallback')">`:'<span class="culture-text-art" aria-label="No artwork; text-only item">${item.japanese}</span>'}
function cultureCard(item,c){const discovered=c.discovered.includes(item.id),owned=c.owned.includes(item.id);return `<article class="card culture-card"><div class="culture-art ${discovered?'':'culture-art-locked'}">${discovered?cultureArt(item):'<span class="culture-mystery" aria-hidden="true">?</span><span class="sr-only">Cultural object not yet discovered</span>'}</div><div class="eyebrow">${item.category}</div><h3>${discovered?item.japanese:'Undiscovered object'}</h3><p>${discovered?`${item.reading} · ${item.english}`:'Learn more to reveal its name.'}</p><span class="tag">${owned?'Owned':discovered?'Discovered':'Hidden'}</span>${discovered?`<button class="btn btn-ghost btn-small" data-culture-view="${item.id}">Read its story</button>${owned?'':`<button class="btn btn-secondary btn-small" data-culture-acquire="${item.id}">Add to collection</button>`}`:''}</article>`}
function cultureDetail(item){const owned=isOwned(item.id);return `<section class="card culture-detail"><div class="culture-art">${cultureArt(item,'detail')}</div><div class="eyebrow">${item.category} · Cultural knowledge</div><h1>${item.japanese}</h1><p class="romaji">${item.reading} · ${item.romaji}</p><button class="btn btn-ghost btn-small" data-speak="${item.reading}" data-audio-id="${item.audioId}" data-audio-type="culture">♪ Hear Japanese</button><h2>${item.english}</h2><p>${item.summary}</p><blockquote>${item.culturalNote}</blockquote>${item.presentation?.type==='text-only'?'<p class="culture-art-note">This is an intentionally text-only collection entry.</p>':''}<p><b>Room placement:</b> ${ROOM_ZONES.find(zone=>zone.id===roomZoneForItem(item))?.label||item.placement.roomZone}</p><p><b>Collection status:</b> ${owned?'Owned':'Discovered — not yet owned'}</p>${owned?'<button class="btn btn-primary" data-go="room">Place in Sakura’s room</button>':`<button class="btn btn-primary" data-culture-acquire="${item.id}">Add to collection</button>`}<button class="btn btn-ghost" data-nav="shop">Back to Shop</button></section>`}

function roomView(){const s=getState(),placed=roomPlacements(s),owned=culturalItems.filter(item=>isOwned(item.id));return `<div><div class="eyebrow">A place shaped by your journey</div><h1 class="page-title">Sakura’s Room</h1><p class="subtitle">Choose where your collected stories live. Each zone holds one owned item.</p></div><section class="room-scene" aria-label="Sakura's room with seven interactive placement zones">${ROOM_ZONES.map(zone=>{const item=placed[zone.id],art=item&&culturalArtwork(item);return `<button class="room-hotspot room-zone-${zone.id} ${item?'filled':''}" data-room-zone="${zone.id}" aria-label="${zone.label}: ${item?item.english:'empty'}">${item?`${art?`<img src="${art}" alt="" loading="lazy" decoding="async">`:''}<span>${item.japanese}</span>`:`<span>＋ ${zone.label}</span>`}</button>`}).join('')}</section><p class="room-help">Select a zone in the room or use the controls below. Placement is also fully described as text.</p><section class="room-controls" aria-label="Room placement controls">${ROOM_ZONES.map(zone=>{const item=placed[zone.id],choices=owned.filter(candidate=>roomZoneForItem(candidate)===zone.id);return `<div class="card room-control" id="room-control-${zone.id}"><div><b>${zone.label}</b><small>${item?`${item.japanese} · ${item.english}`:'Empty'}</small></div><select class="input" data-room-select="${zone.id}" aria-label="Choose an item for ${zone.label}"><option value="">${choices.length?'Choose an owned item':'No matching items owned'}</option>${choices.map(candidate=>`<option value="${candidate.id}" ${item?.id===candidate.id?'selected':''}>${candidate.japanese} · ${candidate.english}</option>`).join('')}</select>${item?`<button class="btn btn-ghost btn-small" data-room-remove="${zone.id}">Remove</button>`:''}</div>`}).join('')}</section>${owned.length?'<p class="room-footnote">Items can only be placed in their culturally appropriate display zone.</p>':'<section class="card empty">Your room is ready. Discover and collect an item in Aoi-san’s Shop to place it here.<br><button class="btn btn-secondary btn-small" data-go="shop">Visit the Shop</button></section>'}`}
function bindRoom(){document.querySelectorAll('[data-room-zone]').forEach(button=>button.onclick=()=>document.querySelector(`#room-control-${button.dataset.roomZone} select`)?.focus());document.querySelectorAll('[data-room-select]').forEach(select=>select.onchange=()=>{if(!select.value)return;const result=placeOwnedItem(select.value);toast(result.ok?`${result.item.japanese} placed in the ${ROOM_ZONES.find(zone=>zone.id===result.zone)?.label.toLowerCase()}.`:'That item cannot be placed there.');render()});document.querySelectorAll('[data-room-remove]').forEach(button=>button.onclick=()=>{removePlacedItem(button.dataset.roomRemove);toast('The space is clear again.');render()})}

function homeView(){const s=getState(),due=dueWords().length,weak=weakWords().length,quests=dailyQuests(),week=weeklyQuest(),mastered=masteredCount(),r=recommendNext(),resume=s.activeSession?.focus,progress=Math.round(curriculumProgress()*100),primary=r.action==='resume'?'<button class="btn btn-primary" data-journey-resume>Continue where you left off <span>→</span></button>':`<button class="btn btn-primary" data-recommend>Start next step <span>→</span></button>`;return `
 <section class="home-welcome sakura-horizon"><div class="home-welcome-copy"><div class="hero-kicker">こんばんは · Welcome back</div><h1>Your next step is ready.</h1><p>Keep your Japanese moving with one clear, calm step. Your saved learning progress chooses what comes next.</p><div class="home-primary card"><div><div class="eyebrow">${r.action==='resume'?'Continue learning':'Recommended next'}</div><h2>${r.title}</h2><p>${r.reason}</p><small>${r.commitment}</small></div><div class="home-primary-actions">${primary}<button class="btn btn-ghost btn-small" data-nav="journey">View Journey</button></div></div></div><div class="sakura-welcome"><img src="./assets/sakura-companion.webp" alt="Sakura, your learning companion" decoding="async"><div class="speech">Good to see you!<br><b>Let’s take one step.</b> ♡</div></div></section>
 <section class="home-progress" aria-label="Learning progress"><div><span>Journey</span><b>${progress}%</b><small>Current trail</small></div><div><span>✓</span><b>${mastered}</b><small>Words mastered</small></div><div><span>文</span><b>${Object.keys(s.grammar).length}</b><small>Grammar learned</small></div><div><span>🔥</span><b>${s.streak}</b><small>Day streak</small></div></section>
 <section class="home-today section"><div class="section-head"><div><div class="eyebrow">Today’s bounded quest</div><h2>Three small markers</h2></div><span>${week.value}/${week.target} study days this week</span></div><div class="card">${quests.map(q=>questRow(q)).join('')}</div></section>
 <section class="focus-quest card"><div><div class="eyebrow">⚡ Need something smaller?</div><h2>Try a Focus Quest.</h2><p>Choose a few focused steps. Stop whenever you want — your progress is saved.</p></div><div class="focus-options">${resume?`<button class="btn btn-primary" data-resume-focus>Continue ${resume.title||'Focus Quest'} →</button><button class="btn btn-ghost btn-small" data-focus-fresh>Start fresh</button>`:Object.values(FOCUS_PROFILES).map(p=>`<button class="focus-option" data-focus="${p.duration}"><b>${p.duration} min</b><small>${p.prompt}</small></button>`).join('')}</div></section>
 <div class="grid grid-2 section"><div><div class="section-head"><h2>Quick practice</h2><span>Choose your focus</span></div><div class="grid grid-3">
   <button class="card action-card" data-start="review"><span class="action-icon">↻</span><h3>Smart Review</h3><p>${due} items due now, scheduled by mastery.</p></button>
   <button class="card action-card" data-start="mistakes"><span class="action-icon">◎</span><h3>Mistake Practice</h3><p>${weak?`${weak} weak words need attention.`:'Builds from patterns in your answers.'}</p></button>
   <button class="card action-card" data-start="kana"><span class="action-icon">あ</span><h3>Kana Training</h3><p>Progress row by row, with confusion drills.</p></button>
 </div></div><div><div class="section-head"><h2>Learning rhythm</h2><span>From saved progress</span></div><div class="card home-rhythm"><b>${due} due · ${weak} need care</b><p>Reviews and recent mistakes remain part of your canonical recommendation.</p></div></div></div>
 <div class="section"><div class="section-head"><h2>Your path</h2><span>Weekly quest: ${week.value}/${week.target} study days</span></div><div class="area-list">${areas.map(areaCard).join('')}</div></div>`}
function questRow(q){const p=Math.min(100,q.value/q.target*100);return `<div class="quest"><span class="quest-icon">${q.icon}</span><div><b>${q.label}</b><div class="bar"><span style="width:${p}%"></span></div></div><span class="quest-count">${Math.min(q.value,q.target)}/${q.target}</span></div>`}
function areaCard(a){const locked=getState().xp<a.unlock,words=a.groups.flatMap(g=>g.words),seen=words.filter(id=>getState().reviews[id]).length;return `<article class="card area-card"><div class="area-top"><span class="area-icon">${a.icon}</span><div><h3>${a.name}</h3><p>${a.description}</p></div></div><div class="bar"><span style="width:${seen/words.length*100}%;background:${a.color}"></span></div><div class="lesson-chips">${a.groups.map(g=>`<button class="chip" data-group="${g.id}" ${locked?'disabled':''}>${g.icon} ${g.name}</button>`).join('')}</div>${locked?`<div class="locked">🔒 Reach ${a.unlock} XP<br><small>${a.unlock-getState().xp} XP to go</small></div>`:''}</article>`}

function learnView(){const unlocked=currentGrammar();return `<div class="section-head"><div><div class="eyebrow">Structured learning</div><h1 class="page-title">Learning path</h1><p class="subtitle">Each chapter prepares the language you need for the story challenge ahead.</p></div></div>${sakuraPresence('learning')}
 <section class="section"><div class="section-head"><h2>Adventure trail</h2><span>${curriculum.filter(nodeComplete).length}/${curriculum.length} chapters complete</span></div><div class="path-map">${curriculum.map((n,i)=>pathNode(n,i)).join('')}</div></section>
 <section class="section"><div class="section-head"><h2>Kana path</h2><span>Families unlock with progress</span></div><div class="kana-families">${kanaFamilies.map((f,i)=>kanaFamilyCard(f,i)).join('')}</div></section>
 <section class="section"><div class="section-head"><h2>Grammar trail</h2><span>${Object.keys(getState().grammar).length}/${grammar.length} structures learned</span></div><div class="grammar-grid">${grammar.map(g=>grammarCard(g,unlocked.some(x=>x.id===g.id))).join('')}</div></section>
 <section class="section"><div class="section-head"><h2>Conversation worlds</h2><label class="toggle"><input id="typingToggle" type="checkbox" ${conversationTyping?'checked':''}> Type my answers</label></div><div class="scenario-grid">${scenarios.filter(sc=>getState().xp>=areas.find(a=>a.id===sc.area).unlock).map(scenarioCard).join('')}</div></section>`}
function nodeIcon(type){return {kana:'あ',vocabulary:'言',grammar:'文',story:'💬'}[type]||'◆'}
function pathNode(n,i){const done=nodeComplete(n),open=nodeUnlocked(n);return `<div class="path-node ${done?'done':open?'open':'blocked'}"><div class="path-line"></div><button class="path-orb" data-node="${n.id}" ${open||done?'':'disabled'}>${done?'✓':nodeIcon(n.type)}</button><div class="card path-copy"><div class="eyebrow">Chapter ${i+1} · ${n.type}</div><h3>${n.title}</h3><p>${n.subtitle} · ${n.outcome}</p>${!open&&!done?`<small>Requires ${n.requires.map(id=>curriculum.find(x=>x.id===id)?.title).join(', ')}</small>`:''}</div></div>`}
function kanaFamilyCard(f,i){const unlocked=i<=Math.floor(getState().xp/100),total=f.items.reduce((n,[c])=>n+(getState().kana[c]?.correct||0),0);return `<button class="card action-card kana-family" data-family="${f.id}" ${unlocked?'':'disabled'}><span class="action-icon">${f.items[0][0]}</span><h3>${f.name} ${unlocked?'':'🔒'}</h3><div class="kana-row">${f.items.map(x=>x[0]).join(' ')}</div><p>${total} correct answers</p></button>`}
function grammarCard(g,unlocked){const learned=getState().grammar[g.id];return `<article class="card ${unlocked?'':'locked-card'}"><div class="grammar-symbol">${g.title}</div><h3>${g.summary}</h3><div class="pattern">${g.pattern}</div><p><b>${g.example}</b><br>${g.exampleEn}</p><div style="margin-top:14px">${learned?'<span class="learned">✓ In Grammar Journal</span>':unlocked?`<button class="btn btn-secondary btn-small" data-grammar="${g.id}">Mark lesson complete</button>`:'<span class="tag">Unlocks with more XP</span>'}</div></article>`}
function scenarioCard(sc){return `<button class="card action-card scenario-card" data-scenario="${sc.id}"><span class="place">${sc.icon}</span><h3>${sc.place}</h3><p>Talk with ${sc.npc}</p></button>`}

function journalView(){const words=vocabulary.filter(w=>getState().reviews[w.id]),learned=grammar.filter(g=>getState().grammar[g.id]);return `<div><div class="eyebrow">Your collection</div><h1 class="page-title">Journal</h1><p class="subtitle">Every answer shapes mastery and the next review date.</p></div><div class="journal-tools"><button class="btn ${journalType==='words'?'btn-primary':'btn-ghost'} btn-small" data-journal="words">Word Journal · ${words.length}</button><button class="btn ${journalType==='grammar'?'btn-primary':'btn-ghost'} btn-small" data-journal="grammar">Grammar Journal · ${learned.length}</button><input id="journalSearch" class="input search" placeholder="Search Japanese or English…"></div><div id="journalResults">${journalType==='words'?wordCards(words):grammarJournal(learned)}</div>`}
function wordCards(words){if(!words.length)return `<div class="card empty">Words appear here as soon as you meet them in a lesson or journey.</div>`;return `<div class="word-grid">${words.map(wordCard).join('')}</div>`}
function wordCard(w){const r=getState().reviews[w.id],m=mastery(r),skills=skillScores(r);return `<article class="card word-card" data-search="${esc(`${w.kana} ${w.kanji} ${w.romaji} ${w.meaning} ${w.category}`.toLowerCase())}"><div class="word-jp"><div><span class="kana">${w.kana}</span><div class="kanji">${getState().settings.furigana?w.kanji:''}</div></div><button title="Hear pronunciation" aria-label="Hear ${w.kana}" data-speak="${w.kana}">♪</button></div>${getState().settings.romaji?`<div class="romaji">${w.romaji}</div>`:''}<div class="meaning">${w.meaning}</div><span class="tag">${w.category}</span><div class="example"><b>${w.example}</b><br>${w.exampleEn}</div><div class="mastery" title="Mastery ${m} of 5">${[1,2,3,4,5].map(i=>`<i class="${i<=m?'on':''}"></i>`).join('')}</div><div class="skill-mini">${Object.entries(skills).map(([k,v])=>`<span title="${k} ${v}%"><i style="height:${Math.max(3,v/2)}%"></i>${k[0].toUpperCase()}</span>`).join('')}</div></article>`}
function grammarJournal(items){if(!items.length)return `<div class="card empty">Complete a grammar lesson to add its pattern and example here.</div>`;return `<div class="grammar-grid">${items.map(g=>`<article class="card" data-search="${esc((g.title+' '+g.summary).toLowerCase())}"><div class="grammar-symbol">${g.title}</div><h3>${g.summary}</h3><div class="pattern">${g.pattern}</div><p><b>${g.example}</b><br>${g.exampleEn}</p></article>`).join('')}</div>`}

function bindJourney(){document.querySelectorAll('[data-journey-node]').forEach(button=>button.onclick=()=>{journeySelection=button.dataset.journeyNode;render()});document.querySelector('[data-journey-close]')?.addEventListener('click',()=>{journeySelection=null;render()});document.querySelectorAll('[data-journey-start]').forEach(button=>button.onclick=()=>openNode(button.dataset.journeyStart));document.querySelector('[data-recommend]')?.addEventListener('click',startRecommended);document.querySelector('[data-journey-resume]')?.addEventListener('click',resumeJourneySession)}
function journeyView(){const map=journeyMap(),r=recommendNext(),selected=journeySelection&&curriculum.find(node=>node.id===journeySelection),discoveries=selected?culturalItems.filter(item=>item.unlock.type==='curriculum'&&item.unlock.value===selected.id):[],detail=selected?`<section class="journey-detail card"><div class="eyebrow">Node detail · ${selected.type}</div><h2>${selected.title}</h2><p>${selected.outcome}</p><p class="journey-detail-meta">Approx. ${selected.type==='story'?'3':selected.type==='kana'?'5':'5'} minutes · ${journeyNodeProgress(selected)}% complete</p>${discoveries.length?`<p class="journey-discovery">🏪 Cultural discovery: ${discoveries.map(item=>nodeComplete(selected.id)?`${item.japanese} · ${item.english}`:'mystery object').join(', ')}</p>`:''}${nodeUnlocked(selected)?`<button class="btn btn-primary" data-journey-start="${selected.id}">Begin lesson →</button>`:`<p class="locked-reason">🔒 Complete ${selected.requires.map(id=>curriculum.find(node=>node.id===id)?.title||id).join(' and ')} first.</p>`}<button class="btn btn-ghost btn-small" data-journey-close>Close</button></section>`:'';return `<div><div class="eyebrow">Your route through Japanese</div><h1 class="page-title">Quest Journey</h1><p class="subtitle">The curriculum is your path. Each step teaches something, and the next one is always visible.</p></div>${r.action==='node'?`<section class="journey-next card"><div><div class="eyebrow">Recommended next</div><h2>${r.title}</h2><p>${r.reason}</p><small>${r.commitment}</small></div><button class="btn btn-primary" data-recommend>Begin →</button></section>`:''}${detail}<div class="journey-map section">${map.map((chapter,index)=>`<section class="journey-chapter"><div class="section-head"><div><div class="eyebrow">Chapter ${index+1}</div><h2>${chapter.title}</h2></div><span>${chapter.progress}% complete</span></div><p class="journey-chapter-subtitle">${chapter.subtitle}</p><div class="journey-path">${chapter.nodes.map(node=>`<article class="journey-node ${node.status}" data-status="${node.status}"><div class="journey-node-rail"></div><div class="journey-node-marker">${node.status==='completed'?'✓':node.type==='kana'?'あ':node.type==='vocabulary'?'言':node.type==='grammar'?'文':node.type==='story'?'話':'聞'}</div><button class="journey-node-body" data-journey-node="${node.id}" aria-label="${node.title}, ${node.status}${node.lockedReason?`. ${node.lockedReason}`:''}"><span class="eyebrow">${node.type} · ${node.status}</span><b>${node.title}</b><small>${node.status==='locked'||node.status==='future'?node.lockedReason||'Coming later':`${node.progress}% complete · ${node.outcome}`}</small></button></article>`).join('')}</div></section>`).join('')}</div><section class="journey-escape card"><div><div class="eyebrow">Not feeling a lesson?</div><h2>Do a tiny Focus Quest</h2><p>Structured progress is optional. Real practice still moves your Garden and Journey forward.</p></div><button class="btn btn-ghost" data-focus="2">⚡ 2-minute Focus Quest</button></section>`}
function gardenView(){const s=getState(),p=gardenProgress(s),nextUnlock=GARDEN_UNLOCKS.find(item=>!p.unlocked.includes(item.id)),recent=s.garden?.recentGrowth||[],elements=[['first-blossom','🌸'],['stone-path','🪨'],['branch','🌿'],['lantern','🏮'],['songbird','🐦'],['moonlit','✨'],['pond','◌']];return `<div><div class="eyebrow">Your learning journey in bloom</div><h1 class="page-title">Sakura Garden</h1><p class="subtitle">Everything here grows from something you have learned. Nothing fades when you take a break.</p></div><section class="garden-scene section garden-level-${p.level}" aria-label="Sakura Garden level ${p.level}, ${p.levelName}. ${p.score} growth points. ${p.unlocked.length} garden elements unlocked."><div class="garden-shade"></div><div class="garden-elements">${elements.map(([id,icon])=>`<span class="garden-element garden-element-${id} ${p.unlocked.includes(id)?'unlocked':''}" aria-label="${GARDEN_UNLOCKS.find(x=>x.id===id)?.label||id}">${icon}</span>`).join('')}</div><div class="garden-level"><span>Garden level ${p.level}</span><b>${p.levelName}</b></div><div class="garden-caption"><h2>${p.levelName}</h2><p>${p.nextLevel?`${p.progressToNext}% toward ${p.nextLevel}`:'Your Garden is in full bloom.'}</p><div class="garden-progress" aria-label="${p.progressToNext}% toward next Garden level"><span style="width:${p.progressToNext}%"></span></div></div></section><section class="garden-summary section"><div class="card garden-growth-card"><div class="eyebrow">Growth ${p.score}</div><h2>Built from real learning</h2><p>Mastery, strengthened kana, grammar, conversations, and completed chapters all leave a different trace.</p><div class="garden-next"><b>Next meaningful unlock</b><span>${nextUnlock?`${nextUnlock.label} — ${nextUnlock.description}`:'Every bounded Garden detail is unlocked.'}</span></div></div><div class="card garden-recent"><div class="section-head"><h2>Recent growth</h2><span>${recent.length?'What changed':'Waiting for your next milestone'}</span></div>${recent.length?`<ul>${recent.slice(0,4).map(item=>`<li>${item}</li>`).join('')}</ul>`:'<p>Learn something meaningful and Sakura will note what grew here.</p>'}</div></section><section class="garden-ledger section" aria-label="Garden learning contributions"><div class="card"><span>🌸</span><b>${p.counts.blossoms}</b><small>Blossoms · mastered words</small></div><div class="card"><span>🪨</span><b>${p.counts.kana}</b><small>Stones · strengthened kana</small></div><div class="card"><span>🏮</span><b>${p.counts.grammar}</b><small>Lanterns · grammar structures</small></div><div class="card"><span>🌿</span><b>${p.counts.branches}</b><small>Branches · curriculum chapters</small></div><div class="card"><span>🐦</span><b>${p.counts.conversations}</b><small>Songbirds · conversations</small></div></section><blockquote>“The more you learn, the more your garden grows.”</blockquote>`}

function companionView(){const s=getState(),presence=companionState(),active=COMPANION_REACTIONS[presence.reaction]||COMPANION_REACTIONS.idle;return `<div><div class="eyebrow">Your persistent learning companion</div><h1 class="page-title">Sakura</h1><p class="subtitle">She reacts to what happens in your learning sessions, so every answer has a little context.</p></div><section class="companion-profile section"><div class="companion-portrait ${active.tone}"><img src="./assets/sakura-companion.webp" alt="Sakura, your learning companion"><div class="reaction-badge">${active.emoji} ${active.label}</div></div><div class="companion-message"><span>こんにちは！</span><h2>${active.message}</h2><p>Current reaction: <b>${active.label}</b>. Sakura updates automatically when you begin a session, answer correctly, make a mistake, complete a lesson, return after time away, or reach a new milestone.</p><div class="companion-effect"><b>Last event</b><span>${presence.event||'SESSION_START'} · ${presence.seenEvents||0} reactions shared</span></div></div></section><section class="section"><div class="section-head"><h2>Reaction states</h2><span>Reusable companion language</span></div><div class="reaction-grid">${Object.entries(COMPANION_REACTIONS).map(([key,r])=>`<article class="card reaction-card ${key===presence.reaction?'active':''}"><span>${r.emoji}</span><div><h3>${r.label}</h3><p>${r.message}</p></div></article>`).join('')}</div></section><div class="profile-actions section"><button class="btn btn-ghost" data-go="settings">⚙ Settings & backup</button><button class="btn btn-ghost" data-go="studio">◇ Content Studio</button></div>`}

function statsView(){const s=getState(),answers=s.answers,correct=answers.filter(a=>a.correct).length,acc=answers.length?Math.round(correct/answers.length*100):0,mastered=Object.values(s.reviews).filter(r=>mastery(r)>=4).length;const cats=[...new Set(vocabulary.map(w=>w.category))].map(c=>{const ids=vocabulary.filter(w=>w.category===c).map(w=>w.id),a=answers.filter(x=>x.kind==='word'&&ids.includes(x.id));return {c,p:a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):0,n:a.length}}).sort((a,b)=>b.p-a.p);return `<div><div class="eyebrow">Learning record</div><h1 class="page-title">Statistics</h1><p class="subtitle">See what is sticking and where to focus next.</p></div><div class="grid stats-grid section"><div class="card"><div class="big-number">${acc}%</div><div class="metric-label">Overall accuracy</div></div><div class="card"><div class="big-number">${mastered}</div><div class="metric-label">Words mastered</div></div><div class="card"><div class="big-number">${Object.keys(s.kana).length}</div><div class="metric-label">Kana practised</div></div><div class="card"><div class="big-number">${s.studyDays.length}</div><div class="metric-label">Study days</div></div></div><div class="grid grid-2 section"><div class="card"><h3>Accuracy by category</h3>${cats.map(x=>`<div class="category-row"><span>${x.c}</span><div class="bar"><span style="width:${x.p}%;background:${x.n? 'var(--blue)':'#dfe3e6'}"></span></div><b>${x.n?x.p+'%':'—'}</b></div>`).join('')}</div><div class="card"><h3>Strongest & weakest</h3><p style="margin:12px 0"><b>Strongest:</b> ${cats.find(x=>x.n)?.c||'Complete a lesson first'}</p><p><b>Needs practice:</b> ${[...cats].reverse().find(x=>x.n)?.c||'No mistakes recorded yet'}</p><h3 style="margin-top:22px">Recent accuracy</h3>${weekBars(answers)}</div></div><section class="section"><div class="section-head"><h2>Achievements</h2><span>Learning milestones</span></div><div class="achievement-grid">${achievementData.map(a=>`<div class="card achievement ${s.achievements.includes(a.id)?'':'locked'}"><span class="achievement-icon">${a.icon}</span><div><h3>${a.name}</h3><p>${a.detail}</p></div></div>`).join('')}</div></section>`}
function weekBars(answers){return `<div style="display:flex;gap:8px;align-items:end;height:100px;margin-top:14px">${[6,5,4,3,2,1,0].map(d=>{const day=new Date(Date.now()-d*86400000).toISOString().slice(0,10),a=answers.filter(x=>x.date.startsWith(day)),p=a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):4;return `<div style="flex:1;text-align:center"><div style="height:${p}px;background:${a.length?'var(--blue)':'#e8ebed'};border-radius:5px 5px 2px 2px"></div><small>${new Date(day).toLocaleDateString(undefined,{weekday:'narrow'})}</small></div>`}).join('')}</div>`}

function studioView(){const report=validateContent(),sample=`{\n  "id": "word.unique-id",\n  "kana": "...",\n  "kanji": "...",\n  "romaji": "...",\n  "meaning": "...",\n  "category": "...",\n  "difficulty": 1,\n  "area": "sakura",\n  "example": "...",\n  "exampleEn": "..."\n}`;return `<div><div class="eyebrow">Curriculum workshop</div><h1 class="page-title">Content Studio</h1><p class="subtitle">Inspect the learning graph and validate content before it becomes part of the game.</p></div><div class="grid grid-2 section"><section class="card"><div class="validation-head"><span class="validation-mark ${report.valid?'valid':'invalid'}">${report.valid?'✓':'!'}</span><div><h3>${report.valid?'Content is ready':'Content needs attention'}</h3><p>${report.issues.length?`${report.issues.length} issues found`:'All stable IDs, references and required learning fields passed.'}</p></div></div><div class="content-counts">${Object.entries(report.counts).map(([k,v])=>`<div><b>${v}</b><span>${k}</span></div>`).join('')}</div>${report.issues.map(i=>`<div class="issue"><b>${i.where}</b> ${i.message}</div>`).join('')}</section><section class="card"><h3>Add a vocabulary record</h3><p>Copy this schema into the curriculum data file. Validation catches missing fields, duplicate IDs and broken references.</p><pre class="schema-code">${esc(sample)}</pre><button class="btn btn-secondary btn-small" id="copySchema">Copy schema</button></section></div><section class="card section"><div class="section-head"><h2>Prerequisite graph</h2><span>Schema v${contentManifest.schemaVersion}</span></div><div class="manifest-list">${curriculum.map(n=>`<div><b>${n.id}</b><span>${n.type}</span><small>${n.requires.length?n.requires.join(' → '):'entry point'}</small></div>`).join('')}</div></section>`}

function settingsView(){const s=getState();return `<div><div class="eyebrow">Make it yours</div><h1 class="page-title">Settings & backup</h1><p class="subtitle">Choose how Japanese appears and protect your learning history.</p></div><div class="grid settings-grid section"><section class="card"><h3>Learning display</h3>${toggleSetting('romaji','Show romaji','Latin reading beneath Japanese')}${toggleSetting('furigana','Show kanji forms','Display kanji beneath kana')}${toggleSetting('sound','Sound & pronunciation','Allow speech playback')}${toggleSetting('reducedMotion','Reduced animation','Remove movement and transitions')}<div class="setting-row"><div><b>Text size</b><small>Interface font size</small></div><select class="input" data-setting="fontSize"><option value="16" ${s.settings.fontSize==16?'selected':''}>Standard</option><option value="18" ${s.settings.fontSize==18?'selected':''}>Large</option><option value="20" ${s.settings.fontSize==20?'selected':''}>Extra large</option></select></div><div class="setting-row"><div><b>Journey length</b><small>Steps in a generated session</small></div><select class="input" data-setting="sessionLength"><option value="5" ${s.settings.sessionLength==5?'selected':''}>5 steps</option><option value="7" ${s.settings.sessionLength==7?'selected':''}>7 steps</option><option value="10" ${s.settings.sessionLength==10?'selected':''}>10 steps</option></select></div></section><section class="card"><h3>Sakura companion</h3><p>Sakura reacts to your learning events automatically. Visit her profile to see the current reaction and dialogue state.</p><button class="btn btn-secondary btn-small" data-go="companion" style="margin-top:14px">View Sakura</button></section></div><section class="card section"><h3>Save backup</h3><p>Export a copy before moving browsers or devices. Importing replaces the progress currently stored here.</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:15px"><button class="btn btn-secondary" id="exportSave">↓ Export save</button><label class="btn btn-ghost">↑ Import save<input id="importSave" type="file" accept="application/json" hidden></label><button class="btn btn-danger" id="resetSave">Reset progress</button></div></section>`}
function settingsAudioCard(){const s=getState(),voices=getJapaneseVoices();return `<section class="card"><h3>Japanese audio</h3><p>Pronunciation uses checked-in audio when available, then your browser’s Japanese voice.</p><div class="setting-row"><div><b>Voice</b><small>Japanese voice preference</small></div><select class="input" data-audio-setting="voice"><option value="auto">Auto</option>${voices.map(v=>`<option value="${esc(v.voiceURI||v.name)}" ${s.audio?.voice===(v.voiceURI||v.name)?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div><div class="setting-row"><div><b>Playback speed</b><small>Slow helps careful listening</small></div><select class="input" data-audio-setting="speed"><option value="slow" ${s.audio?.speed==='slow'?'selected':''}>Slow</option><option value="normal" ${!s.audio?.speed||s.audio?.speed==='normal'?'selected':''}>Normal</option><option value="fast" ${s.audio?.speed==='fast'?'selected':''}>Fast</option></select></div><label class="setting-row"><div><b>Auto-play listening</b><small>Play eligible listening prompts once</small></div><input type="checkbox" data-audio-setting="autoPlay" ${s.audio?.autoPlay?'checked':''}></label><details><summary>Audio diagnostics</summary><pre>${esc(JSON.stringify(audioDiagnostics(),null,2))}</pre></details></section>`}
function bindAudioSettings(){document.querySelectorAll('[data-audio-setting]').forEach(el=>el.onchange=()=>{const key=el.dataset.audioSetting,value=el.type==='checkbox'?el.checked:el.value;update(s=>s.audio={...(s.audio||{}),[key]:value});render()})}
function toggleSetting(id,title,detail){return `<label class="setting-row"><div><b>${title}</b><small>${detail}</small></div><input type="checkbox" data-setting="${id}" ${getState().settings[id]?'checked':''}></label>`}

function startFocus(duration=5){duration=FOCUS_PROFILES[duration]?duration:5;const built=buildFocusSession(duration);if(!built.items.length){toast('No Focus Quest material is ready yet — try a lesson instead.');return}update(s=>s.focus.lastDuration=duration);session={id:`${Date.now()}-${Math.random().toString(36).slice(2)}`,kind:'focus',title:FOCUS_PROFILES[duration].label,nodeId:null,focus:true,duration,budget:built.budget,items:built.items.map(makeQuestion),index:0,score:0,answered:false,protected:false,gardenStartScore:gardenProgress().score,focusStarted:Date.now()};persistSession();emitCompanion(COMPANION_EVENTS.QUEST_STARTED,{message:'A few focused steps are ready when you are.',focus:true});render()}
function resumeFocus(){const saved=getState().activeSession;if(!saved?.focus){startFocus(getState().focus?.lastDuration||5);return}const duration=FOCUS_PROFILES[saved.duration]?saved.duration:(getState().focus?.lastDuration||5);const built=buildFocusSession(duration);session={id:saved.id,kind:'focus',title:saved.title||FOCUS_PROFILES[duration].label,nodeId:null,focus:true,duration,budget:built.budget,items:built.items.map(makeQuestion),index:focusResumeIndex(saved,built.items.length),score:saved.score||0,answered:false,protected:false,gardenStartScore:saved.gardenStartScore??gardenProgress().score,focusStarted:Date.now()};persistSession();render()}
function extendFocus(){if(!session?.focus)return;const extra=buildFocusSession(2);session.items.push(...extra.items.map(makeQuestion));session.budget=session.items.length;session.done=false;session.extended=(session.extended||0)+2;persistSession();render()}
function resumeJourneySession(){const saved=getState().activeSession;if(!saved)return;if(saved.focus){resumeFocus();return}if(saved.conversation&&saved.scenarioId)return startConversation(saved.scenarioId,saved.nodeId||null,saved);if(saved.nodeId){const node=curriculum.find(item=>item.id===saved.nodeId);if(node)return startSession('curriculum',curriculumItems(node),node.title,node.id,saved)}if(saved.kind==='review'){const built=buildSession('review');return startSession('review',built.items,saved.title||'Smart Review',null,saved)}if(saved.kind==='mistakes'){const built=buildSession('mistakes');return startSession('mistakes',built.items,saved.title||'Mistake Practice',null,saved)}const built=buildSession('journey');startSession('journey',built.items,saved.title||"Today's Journey",null,saved)}
function startRecommended(){const r=recommendNext();if(r.action==='resume')return resumeJourneySession();if(r.action==='node')return openNode(r.nodeId);if(r.action==='review'){const built=buildSession('review',{length:5});return startSession('review',built.items,'Smart Review')}if(r.action==='mistakes'){const built=buildSession('mistakes');return startSession('mistakes',built.items,'Mistake Practice')}startFocus(2)}
function startSession(kind,items,title,nodeId=null,checkpoint=null){if(!items.length){toast('Nothing is due yet — try a lesson instead.');return}session={id:checkpoint?.id||`${Date.now()}-${Math.random().toString(36).slice(2)}`,kind,title,nodeId,items:items.map(makeQuestion),index:checkpoint?focusResumeIndex(checkpoint,items.length):0,score:checkpoint?.score||0,answered:false,done:Boolean(checkpoint?.answered&&(checkpoint.index||0)>=items.length-1),protected:false};persistSession();emitCompanion(COMPANION_EVENTS.LESSON_STARTED,{message:`${title} is ready when you are.`});render()}
function makeQuestion(item){let question;if(item.type==='kana'){const pool=kanaFamilies.flatMap(f=>f.items).filter(x=>x[1]!==item.romaji);const options=shuffle([item.romaji,...shuffle(pool).slice(0,3).map(x=>x[1])]);question={...item,stage:'recognition',options}}else{const w=item.word,stage=item.stage||'recognition',others=shuffle(vocabulary.filter(x=>x.id!==w.id)).slice(0,3);if(stage==='listening')question={...item,stage,prompt:'♪',sub:'Listen, then choose the meaning',answer:w.meaning,options:shuffle([w.meaning,...others.map(x=>x.meaning)])};else if(stage==='recall')question={...item,stage,prompt:w.meaning,sub:'Type the Japanese reading',answer:w.kana};else if(stage==='production')question={...item,stage,prompt:w.exampleEn,sub:'Type the missing Japanese word',answer:w.kana};else{const byMeaning=Math.random()>.5;question={...item,stage,prompt:byMeaning?w.kana:w.meaning,sub:byMeaning?'Choose the meaning':'Choose the Japanese',answer:byMeaning?w.meaning:w.kana,options:shuffle([byMeaning?w.meaning:w.kana,...others.map(x=>byMeaning?x.meaning:x.kana)])}}}return {...question,engineQuestion:{...createQuestion(question,{source:item.source||session?.kind||'practice'}),focus:Boolean(session?.focus)}}}
function renderSession(){const q=session.items[session.index],pct=session.index/session.items.length*100;if(session.done){if(session.focus){const gardenGrew=gardenProgress().score>(session.gardenStartScore||0);return `<div class="focus-complete"><div class="eyebrow">⚡ Focus Quest complete</div><h1>That’s enough for today.</h1><p>${session.items.length} focused steps · ${session.score} strengthened · ${session.items.length-session.score} tricky ones found</p>${gardenGrew?'<p class="focus-garden-note">🌸 Your Garden grew a little today.</p>':''}<div class="focus-complete-actions"><button class="btn btn-primary" id="finishSession">Finish</button><button class="btn btn-ghost" id="extendFocus">Keep going +2 minutes</button></div><p class="focus-sakura">Sakura: “You did enough. Nice work.”</p></div>`}return `<div class="session-wrap"><div class="reward-card"><img src="./assets/sakura-celebration.webp" alt="Sakura celebrating your lesson"><div class="reward-copy"><div class="eyebrow">Lesson complete</div><h1>Beautiful work!</h1><p>You answered ${session.score} of ${session.items.length} correctly and strengthened your Japanese today.</p><div class="reward-list"><span>🔥 <b>+${session.score*12}</b> learning XP</span><span>✓ <b>${Math.round(session.score/session.items.length*100)}%</b> accuracy</span><span>文 <b>${dueWords().length}</b> reviews remain</span></div><blockquote>“Every little step leads to something amazing.”</blockquote><button class="btn btn-primary" id="finishSession">Continue the path →</button></div></div></div>`};const typed=q.type==='word'&&(q.stage==='recall'||q.stage==='production');return `<div class="${session.focus?'focus-session':'session-wrap'}"><div class="session-head"><button class="btn btn-ghost btn-small" id="exitSession">Stop whenever you want</button><div class="progress"><span style="width:${pct}%"></span></div><b>${session.focus?`${session.index+1} of ${session.items.length}`:`${session.index+1}/${session.items.length}`}</b></div><div class="card quiz-card"><div class="quiz-type">${session.title} · ${q.type==='kana'?'Kana recall':stageLabel(q.stage)}</div>${session.focus?'<p class="focus-note">Your progress is saved after every answer.</p>':''}${q.stage==='listening'?`<button class="listen-button" data-speak="${q.word.kana}" aria-label="Play Japanese audio">♪</button>`:`<button class="btn btn-ghost btn-small" style="margin-top:15px" data-speak="${q.type==='kana'?q.char:q.word.kana}">♪ Hear it</button>`}<div class="prompt-jp ${q.stage==='production'?'sentence-prompt':''}">${esc(q.type==='kana'?q.char:q.prompt)}</div>${q.type==='word'&&q.stage==='recognition'&&getState().settings.romaji?`<div class="prompt-romaji">${q.prompt===q.word.kana?q.word.romaji:''}</div>`:''}<div class="prompt-label">${q.type==='kana'?'Choose the romaji':q.sub}</div>${typed?`<form class="type-answer" id="sessionForm"><input class="input" id="sessionInput" lang="ja" autocomplete="off" placeholder="Type in Japanese…"><button class="btn btn-primary">Check</button></form>`:`<div class="answers">${q.options.map(o=>`<button class="answer" data-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div>`}<div class="feedback" id="feedback"></div><div class="session-actions"><button class="btn btn-primary" id="nextQuestion" hidden>${session.index===session.items.length-1?'See results':'Continue →'}</button></div></div></div>`}
function answerQuestion(value,button){if(session.answered)return;const q=session.items[session.index],result=evaluateAnswer(q.engineQuestion,value);result.focus=Boolean(session.focus);result.attemptId=`${session.id}:${session.index}`;const correct=result.expected;session.answered=true;if(result.correct)session.score++;recordAnswerResult(result);persistSession();document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(b.dataset.answer===correct)b.classList.add('correct')});if(!result.correct&&button)button.classList.add('wrong');const feedback=document.querySelector('#feedback');feedback.innerHTML=result.correct?'Correct! よくできました。':`Almost — the answer is ${esc(correct)}.`;if(q.stage==='listening')feedback.innerHTML+=`<div class="transcript-reveal"><b>${esc(q.word.kana)}</b> · ${esc(q.word.meaning)}</div>`;feedback.style.color=result.correct?'var(--green)':'#a13232';document.querySelector('#nextQuestion').hidden=false}

function bindView(){document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>startFocus(Number(b.dataset.focus)));document.querySelector('[data-resume-focus]')?.addEventListener('click',resumeFocus);document.querySelector('[data-focus-fresh]')?.addEventListener('click',()=>{update(s=>s.activeSession=null);startFocus(getState().focus?.lastDuration||5)});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{const k=b.dataset.start;if(k==='journey'){const built=buildSession('journey');startSession(k,built.items,"Today's Journey")}if(k==='review'){const built=buildSession('review');startSession(k,built.items,'Smart Review')}if(k==='mistakes'){const built=buildSession('mistakes');startSession(k,built.items,'Mistake Practice')}if(k==='kana'){const f=kanaFamilies[Math.min(kanaFamilies.length-1,Math.floor(getState().xp/100))];startSession('focused',f.items.map(([char,romaji])=>({type:'kana',char,romaji,source:'focused practice'})),'Kana Training')}});
 document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{const ids=areas.flatMap(a=>a.groups).find(g=>g.id===b.dataset.group).words;startSession('lesson',ids.map(id=>({type:'word',word:vocabulary.find(w=>w.id===id),source:'focused practice'})),b.textContent.trim())});
 document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{const f=kanaFamilies.find(x=>x.id===b.dataset.family);startSession('kana',f.items.map(([char,romaji])=>({type:'kana',char,romaji,source:'focused practice'})),f.name)});
 document.querySelectorAll('[data-grammar]').forEach(b=>b.onclick=()=>{completeGrammar(b.dataset.grammar);toast('Added to your Grammar Journal.');render()});
 document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>startConversation(b.dataset.scenario));
 document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>openNode(b.dataset.node));
 const tt=document.querySelector('#typingToggle');if(tt)tt.onchange=()=>conversationTyping=tt.checked;
 document.querySelectorAll('[data-journal]').forEach(b=>b.onclick=()=>{journalType=b.dataset.journal;render()});const search=document.querySelector('#journalSearch');if(search)search.oninput=()=>document.querySelectorAll('[data-search]').forEach(x=>x.style.display=x.dataset.search.includes(search.value.toLowerCase())?'':'none');
 bindSpeak();document.querySelectorAll('[data-setting]').forEach(el=>el.onchange=()=>{const key=el.dataset.setting,val=el.type==='checkbox'?el.checked:Number(el.value);update(s=>s.settings[key]=val);render()});document.querySelectorAll('[data-companion]').forEach(b=>b.onclick=()=>{update(s=>s.companion=b.dataset.companion);toast('Companion equipped.');render()});document.querySelector('#copySchema')?.addEventListener('click',async()=>{await navigator.clipboard.writeText('{"id":"word.unique-id","kana":"","kanji":"","romaji":"","meaning":"","category":"","difficulty":1,"area":"sakura","example":"","exampleEn":""}');toast('Vocabulary schema copied.')});bindBackup()}
function bindSession(){document.querySelector('#finishSession')?.addEventListener('click',()=>{const wasFocus=Boolean(session.focus);if(wasFocus)recordFocusSession({duration:session.duration,questionsAttempted:session.items.length,questionsCompleted:session.items.length,completed:true,earlyExit:false,extended:session.extended||0});completeSession({message:wasFocus?'Focus Quest complete — that was enough for today.':`Lesson complete — you answered ${session.score} of ${session.items.length} correctly.`});if(session.nodeId)completeNode(session.nodeId);session=null;persistSession();view=wasFocus?'home':'learn';render()});document.querySelector('#extendFocus')?.addEventListener('click',()=>extendFocus());document.querySelector('#exitSession')?.addEventListener('click',()=>{const checkpoint=getState().activeSession;if(session.focus)recordFocusSession({duration:session.duration,questionsAttempted:session.index+(session.answered?1:0),questionsCompleted:session.index+(session.answered?1:0),completed:false,earlyExit:true,extended:session.extended||0});session=null;if(checkpoint)update(s=>s.activeSession=checkpoint);else persistSession();render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answerQuestion(b.dataset.answer,b));document.querySelector('#sessionForm')?.addEventListener('submit',e=>{e.preventDefault();answerQuestion(document.querySelector('#sessionInput').value,null)});document.querySelector('#nextQuestion')?.addEventListener('click',()=>{session.index++;session.answered=false;if(session.index>=session.items.length)session.done=true;persistSession();render()});bindSpeak();const q=session.items?.[session.index];if(q?.stage==='listening')setTimeout(()=>speak(q.word.kana),250)}
function bindSpeak(){document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>playAudioButton(b));document.querySelectorAll('.quiz-card .prompt-jp').forEach(b=>{b.tabIndex=0;b.setAttribute('role','button');b.setAttribute('aria-label','Hear Japanese conversation line');b.onclick=()=>playJapanese({text:b.textContent,type:'conversation'})})}
function playAudioButton(button){playJapanese({text:button.dataset.speak,contentId:button.dataset.audioId||null,type:button.dataset.audioType||'vocabulary'}).then(result=>{if(result.reason==='disabled')toast('Sound is turned off in Settings.');if(result.reason==='unavailable')toast('Japanese audio is unavailable in this browser.')})}
function speak(text){playJapanese({text,type:'vocabulary'}).then(result=>{if(result.reason==='disabled')toast('Sound is turned off in Settings.');if(result.reason==='unavailable')toast('Japanese audio is unavailable in this browser.')})}

function openNode(id){const n=curriculum.find(x=>x.id===id);if(!n||(!nodeUnlocked(n)&&!nodeComplete(n)))return;if(n.type==='vocabulary'||n.type==='kana')startSession('curriculum',curriculumItems(n),n.title,n.id);else if(n.type==='grammar'){n.content.forEach(completeGrammar);completeNode(n.id);toast('Grammar patterns added to your journal.');render()}else if(n.type==='story')startConversation(n.content[0],n.id)}
function startConversation(id,nodeId=null,checkpoint=null){const sc=scenarios.find(x=>x.id===id);if(!sc)return;session={id:checkpoint?.id||`${Date.now()}-${Math.random().toString(36).slice(2)}`,conversation:true,kind:'conversation',title:sc.place,nodeId,sc,sceneIndex:checkpoint?Math.min((checkpoint.sceneIndex||0)+(checkpoint.answered?1:0),(sc.scenes?.length||1)-1):0,perfect:true,answered:false};persistSession();app.innerHTML=shell(renderConversation());bindShell();bindConversation()}
function renderConversation(){const {sc}=session,scenes=sc.scenes||[sc],scene=scenes[session.sceneIndex];if(session.done)return `<div class="session-wrap"><div class="card quiz-card"><div class="action-icon">💬</div><h1 class="page-title">Story chapter complete</h1><p class="subtitle">You handled ${scenes.length} exchanges with ${sc.npc}${session.perfect?' without a mistake':''}.</p><div class="pattern" style="font-size:1rem;margin:28px 0"><b>${scene.model}</b><br>${scene.translation}</div><button class="btn btn-primary" id="finishConversation">Continue the story</button></div></div>`;return `<div class="session-wrap"><div class="session-head"><button class="btn btn-ghost btn-small" id="exitSession">× Exit</button><div class="progress"><span style="width:${session.sceneIndex/scenes.length*100}%"></span></div><b>${session.sceneIndex+1}/${scenes.length}</b></div><div class="card quiz-card"><div class="quiz-type">${sc.icon} ${sc.place} · Conversation with ${sc.npc}</div><div class="prompt-jp" style="font-size:2.4rem">${scene.prompt}</div><div class="prompt-label">${scene.translation}</div>${conversationTyping?`<form id="conversationForm" class="type-answer"><input class="input" id="conversationInput" lang="ja" autocomplete="off" placeholder="Type your answer in Japanese…"><button class="btn btn-primary">Reply</button></form>`:`<div class="answers">${shuffle(scene.answers).map(a=>`<button class="answer" data-reply="${a}">${a}</button>`).join('')}</div>`}<div class="feedback" id="feedback"></div><div class="session-actions"><button class="btn btn-primary" id="continueConversation" hidden>${session.sceneIndex===scenes.length-1?'Finish chapter →':'Next exchange →'}</button></div></div></div>`}
function bindConversation(){document.querySelector('#finishConversation')?.addEventListener('click',()=>{if(session.nodeId)completeNode(session.nodeId);session=null;persistSession();view='learn';render()});document.querySelector('#exitSession')?.addEventListener('click',()=>{const checkpoint=getState().activeSession;session=null;if(checkpoint)update(s=>s.activeSession=checkpoint);else persistSession();render()});const scenes=session.sc.scenes||[session.sc],scene=scenes[session.sceneIndex];const submit=value=>{if(session.answered)return;const result=evaluateConversationAnswer({scenarioId:session.sc.id,sceneIndex:session.sceneIndex,answers:scene.answers,model:scene.model},value),ok=result.correct;session.answered=true;session.perfect=session.perfect&&ok;if(session.sceneIndex===scenes.length-1)completeConversation(session.sc.id,session.perfect);persistSession();const f=document.querySelector('#feedback');f.innerHTML=ok?'自然です！ Great answer.':`Good attempt. A natural reply is <b>${scene.model}</b>`;f.style.color=ok?'var(--green)':'#a56a15';document.querySelector('#continueConversation').hidden=false};document.querySelector('#conversationForm')?.addEventListener('submit',e=>{e.preventDefault();submit(document.querySelector('#conversationInput').value)});document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>submit(b.dataset.reply));document.querySelector('#continueConversation')?.addEventListener('click',()=>{session.sceneIndex++;session.answered=false;if(session.sceneIndex>=scenes.length){session.sceneIndex=scenes.length-1;session.done=true}persistSession();app.innerHTML=shell(renderConversation());bindShell();bindConversation()})}
function bindBackup(){document.querySelector('#exportSave')?.addEventListener('click',()=>{const blob=new Blob([exportSave()],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`nihongo-quest-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Save exported.')});document.querySelector('#importSave')?.addEventListener('change',async e=>{try{importSave(await e.target.files[0].text());toast('Progress restored.');render()}catch(err){toast(err.message)}});document.querySelector('#resetSave')?.addEventListener('click',()=>{if(confirm('Reset all learning progress on this device?')){resetSave();toast('Progress reset.');render()}})}

document.addEventListener('click',event=>{const acquire=event.target.closest('[data-culture-acquire]');if(acquire){const result=acquireItem(acquire.dataset.cultureAcquire);if(result.ok&&!result.duplicate){toast(`${result.item.japanese} added to your collection.`);render()}return}const reveal=event.target.closest('[data-culture-view]');if(reveal){const item=culturalItems.find(x=>x.id===reveal.dataset.cultureView);if(item&&isDiscovered(item.id)){acknowledgeCulturalItem(item.id);app.innerHTML=shell(cultureDetail(item));bindShell();bindSpeak()}}});
function decorateAoiShop(){const host=document.querySelector('.shopkeeper-placeholder');if(!host||host.dataset.aoiReady)return;const reaction=companionState().reaction||'idle',expression=STOREKEEPER_REACTION_MAP[reaction]||'neutral',portrait=STOREKEEPER.imageSlots.expressions[expression]||STOREKEEPER.imageSlots.portrait;host.dataset.aoiReady='true';host.removeAttribute('aria-label');host.className='shopkeeper-portrait';host.innerHTML=`<img src="${portrait}" alt="${STOREKEEPER.displayName}, ${expression} expression" onerror="this.hidden=true;this.parentElement.textContent='👵'">`;const card=document.querySelector('.shopkeeper-card');if(card&&!card.querySelector('.shop-branding')){const brand=document.createElement('img');brand.className='shop-branding';brand.src=SHOP_BRANDING.image;brand.alt=SHOP_BRANDING.label;brand.onerror=()=>{brand.hidden=true};card.prepend(brand)}}
const aoiObserver=new MutationObserver(decorateAoiShop);aoiObserver.observe(app,{childList:true,subtree:true});
const sceneObserver=new MutationObserver(()=>mountRegisteredScenes(app));sceneObserver.observe(app,{childList:true,subtree:true});mountRegisteredScenes(app);
syncGardenProgress({announce:false});syncCulturalDiscoveries({announce:false});initializeCompanion();subscribeCompanion(()=>{if(!session)render()});update(()=>{});render();
